<script>
document.addEventListener('DOMContentLoaded', () => {
  const dataContainer = document.querySelector('.status-data-container'); if (!dataContainer) return;
  const avatarDatabase = { '白石莉音': 'https://img.remit.ee/api/file/BQACAgUAAyEGAASHRsPbAAI1K2h3EP69X2r_fNM05HmMSWislv3FAAL5GQAC5vu4V94P86ZWf0H-NgQ.png',
 '早乙女玲奈': 'https://img.remit.ee/api/file/BQACAgUAAyEGAASHRsPbAAI1LWh3EP5KszYMCDehOD-crU4yFGGaAAL7GQAC5vu4V52lmPUwHQLiNgQ.png',
 '如月莲': 'https://img.remit.ee/api/file/BQACAgUAAyEGAASHRsPbAAI1LGh3EP5fUINWBfKkNWD84nPwsqUeAAL6GQAC5vu4V5trs9B2QIHZNgQ.png',};
  function parseData(text) { const data = { characters: {}, live: { messages: [], status:'离线' }, user: { bounties: [] } }; let currentBlockName = ''; let currentBlock = {}; const lines = text.split('\n'); for (const line of lines) { const blockMatch = line.match(/^\s*\[([^\]]+)\]\s*$/); if (blockMatch) { if (currentBlockName) { if(currentBlockName === '全局') data.global = currentBlock; else if(currentBlockName === '直播间') data.live = {...data.live, ...currentBlock}; else if(currentBlockName === '{{user}}') data.user = {...data.user, ...currentBlock}; else data.characters[currentBlockName] = currentBlock; } currentBlockName = blockMatch[1].trim(); currentBlock = {}; } else { const parts = line.split(':'); if(parts.length < 2) continue; const key = parts[0].trim(); const value = parts.slice(1).join(':').trim(); if (currentBlockName === '直播间' && (key.startsWith('弹幕') || key.startsWith('评论'))) { data.live.messages.push(value); } else if (currentBlockName === '{{user}}' && key.startsWith('悬赏任务')) { data.user.bounties.push(value); } else { currentBlock[key] = value; } } } if (currentBlockName === '直播间') data.live = {...data.live, ...currentBlock}; if (data.live.评论1 && !data.live.弹幕1) data.live.status='离线'; else data.live.status='直播中'; return data; }
  function renderStatus(data) { const globalInfoEl = document.querySelector('.grimoire-global-info'); const tabsEl = document.querySelector('.grimoire-tabs'); if (!globalInfoEl || !tabsEl || !data.global) return; globalInfoEl.innerHTML = `<span><svg viewBox="0 0 24 24"><path d="M12,2A10,10 0 0,0 2,12A10,10 0 0,0 12,22A10,10 0 0,0 22,12A10,10 0 0,0 12,2Z"></path></svg>${data.global['时间']||''}</span><span><svg viewBox="0 0 24 24"><path d="M19,19H5V8H19M19,3H18V1H16V3H8V1H6V3H5C3.89,3 3,3.9 3,5V19A2,2 0 0,0 5,21H19A2,2 0 0,0 21,19V5A2,2 0 0,0 19,3Z"></path></svg>${data.global['日期']||''}</span><span><svg viewBox="0 0 24 24"><path d="M12,11.5A2.5,2.5 0 0,1 9.5,9A2.5,2.5 0 0,1 12,6.5A2.5,2.5 0 0,1 14.5,9A2.5,2.5 0 0,1 12,11.5M12,2A7,7 0 0,0 5,9C5,14.25 12,22 12,22C12,22 19,14.25 19,9A7,7 0 0,0 12,2Z"></path></svg>${data.global['地点']||''}</span>`; tabsEl.innerHTML = ''; const tabOrder = ['{{user}}', '白石莉音', '早乙女玲奈', '如月莲', '直播间']; tabOrder.forEach(name => { const isLiveTab = name === '直播间'; const isUser = name === '{{user}}'; if ((isLiveTab && !data.live) || (isUser && !data.user) || (!isLiveTab && !isUser && !data.characters[name])) return; const tab = document.createElement('div'); tab.className = 'grimoire-tab'; tab.dataset.char = name; tab.textContent = isUser ? '{{user}}' : name; tab.addEventListener('click', () => { document.querySelectorAll('.grimoire-tab').forEach(t=>t.classList.remove('active')); document.querySelectorAll('.grimoire-live-view, .grimoire-char-view, .grimoire-user-view').forEach(v=>v.style.display='none'); tab.classList.add('active'); if(isLiveTab) renderLive(data.live); else if(isUser) renderUser(data.user); else renderCharacter(name, data.characters[name]); }); tabsEl.appendChild(tab); }); const firstTab = tabsEl.querySelector('.grimoire-tab'); if (firstTab) firstTab.click(); }
