  function renderLive(liveData) { const view = document.querySelector('.grimoire-live-view'); view.style.display = 'block'; const isLive = liveData['状态'] === '直播中'; let contentTitle = isLive ? '实时弹幕' : '离线评论'; let messagesHtml = (liveData.messages || []).map(d => `<div class="grimoire-message-item">${d}</div>`).join(''); view.innerHTML = `<div class="grimoire-live-header"><div class="grimoire-live-title-container"><div class="grimoire-live-status-dot ${isLive ? 'live' : ''}"></div><div class="grimoire-live-title">${liveData['标题'] || '状态未知'}</div></div><div class="grimoire-live-viewers">${isLive ? `<svg viewBox="0 0 24 24"><path d="M12,9A3,3 0 0,0 9,12A3,3 0 0,0 12,15A3,3 0 0,0 15,12A3,3 0 0,0 12,9M12,4.5C17,4.5 21.27,7.61 23,12C21.27,16.39 17,19.5 12,19.5C7,19.5 2.73,16.39 1,12C2.73,7.61 7,4.5 12,4.5M3.18,12C4.83,15.36 8.24,17.5 12,17.5C15.76,17.5 19.17,15.36 20.82,12C19.17,8.64 15.76,6.5 12,6.5C8.24,6.5 4.83,8.64 3.18,12Z"></path></svg><span>${liveData['观众']||'0'}</span>` : ''}</div></div><div class="grimoire-section-title">${contentTitle}</div><div class="grimoire-message-container">${messagesHtml || `<div class="grimoire-message-item" style="color:var(--grimoire-text-dark);">无</div>`}</div>`; }
  const toggleBtn = document.querySelector('.grimoire-toggle-btn'); const contentEl = document.querySelector('.grimoire-content'); toggleBtn.addEventListener('click', () => { if(contentEl.style.display === 'none'){contentEl.style.display = 'block'; toggleBtn.textContent = '折叠';}else{contentEl.style.display = 'none'; toggleBtn.textContent = '展开';}}); const rawData = dataContainer.textContent.trim(); if(rawData){const parsedData = parseData(rawData); renderStatus(parsedData);}
});
</script>

</body>
